use hy_emit::emit_go; use hy_syntax::parse_file;
#[test] fn select_arm_recv_and_send_try_hoist_and_wrap_main() { let g = emit_go(&parse_file("t.hy", "fn gc() (chan int, error) { return make(chan int, 1), nil }\nfn nv() (int, error) { return 7, nil }\nfn main() {\n ch := make(chan int, 1)\n select {\n v := <-gc()? => { _ = v }\n ch <- nv()? => {}\n default => {}\n }\n}\n").unwrap()).unwrap(); assert!(g.contains("hyT0, hyErr1 := gc()") && g.contains("hyT2, hyErr3 := nv()") && g.contains("case v := <-hyT0:") && g.contains("case ch <- hyT2:") && g.contains("hyErr := func() (hyErr error)"), "{g}"); }
